    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                if v == t:
                    return -1  # Negative cycle reachable from s, so no shortest path
                # If t is not reachable due to cycle, continue checking

    # Check if t is reachable
    if dist[t] == float('inf'):
        return -1

    return dist[t]

