import math

def solve(n, edges, s, t):
    from collections import defaultdict

    if s == t:
        return 0

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = {i: math.inf for i in range(n)}
    dist[s] = 0

    visited = set()

    while True:
        u = None
        min_dist = math.inf
        for node in range(n):
            if dist[node] < min_dist and node not in visited:
                min_dist = dist[node]
                u = node

        if u is None or min_dist == math.inf:
            break

        visited.add(u)

        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w

    return dist[t] if dist[t] != math.inf else -1

