def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import defaultdict
    import heapq

    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm
    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]

