class Node:
    def __init__(self, name):
        self.name = name
        self.neighbors = []
        self.dist = float('inf')
        self.visited = False

    def add_neighbor(self, neighbor):
        self.neighbors.append(neighbor)

def dijkstra(start):
    start.dist = 0
    priority_queue = [(0, start)]
    while priority_queue:
        dist_u, u = min(priority_queue)
        priority_queue.remove((dist_u, u))
        if u.visited:
            continue
        u.visited = True
        for v in u.neighbors:
            if not v.visited and u.dist + 1 < v.dist:
                v.dist = u.dist + 1
                priority_queue.append((v.dist, v))
    return start.dist

class Graph:
    def __init__(self):
        self.nodes = {}

    def add_node(self, name):
        self.nodes[name] = Node(name)

    def add_edge(self, u, v):
        if u not in self.nodes:
            self.nodes[u] = Node(u)
        if v not in self.nodes:
            self.nodes[v] = Node(v)
        self.nodes[u].add_neighbor(self.nodes[v])
        self.nodes[v].add_neighbor(self.nodes[u])

    def get_distance(self, s, t):
        if s not in self.nodes or t not in self.nodes:
            return -1
        dijkstra(self.nodes[s])
        return self.nodes[t].dist

