def count_valid_paths(n, edges, s, t, man, house):
    # Build an adjacency list
    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # List of forbidden nodes (man and house)
    forbidden = set()
    if man is not None:
        forbidden.add(man)
    if house is not None:
        forbidden.add(house)

    # DFS to count paths from s to t, avoiding forbidden nodes
    def dfs(node, visited):
        if node == t:
            return 1
        total = 0
        for neighbor in graph[node]:
            if neighbor not in forbidden and neighbor not in visited:
                visited.add(neighbor)
                total += dfs(neighbor, visited)
                visited.remove(neighbor)
        return total

    # Start DFS from s
    visited = set([s])
    return dfs(s, visited)

