        if len(arr) <= 5:
            return sorted(arr)[len(arr) // 2]
        subarrays = [arr[i*5:(i+1)*5] for i in range((len(arr)+4) // 5)]
        medians = [median_of_medians(sub) for sub in subarrays]
        return median_of_medians(medians)

