        return abs(cell[0] - goal[0]) + abs(cell[1] - goal[1])

    visited = set()
    priority_queue = [(heuristic(start), start)]
    came_from = {}

    while priority_queue:
        _, current = heapq.heappop(priority_queue)
        if current in visited:
            continue
        if current == goal:
            break
        visited.add(current)
        for dr, dc in directions:
