def solve(n, edges, s, t):
    # Build the graph as an adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax all edges up to n-1 times
    for i in range(n-1):
        updated = False
        for u in graph:
            for v, w in graph[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check if t is reachable
    if dist[t] == float('inf'):
        return -1
    else:
        return int(dist[t])

