def solve(n, edges):
    # Initialize adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Precompute for each node, the index it maps to
    node_to_index = {u: i for i, u in enumerate(range(n))}

    # Function to check if there's a path from u to v
    def has_path(u, v):
        if u == v:
            return True
        visited = set()
        stack = [u]
        while stack:
            node = stack.pop()
            if node == v:
                return True
            if node in visited:
                continue
            visited.add(node)
            for neighbor, _ in adj[node]:
                if neighbor not in visited:
                    stack.append(neighbor)
        return False

    # Function to check if all nodes in the path are reachable
    def is_valid_path(u, v, path):
        for i in range(len(path) - 1):
            if not has_path(path[i], path[i+1]):
                return False
        return True

    # Function to find the minimum path length
    def find_min_path_length(u, v):
        visited = set()
        queue = [(u, 0, [u])]
        while queue:
            current, length, path = queue.pop(0)
            if current == v:
                return length
            if current in visited:
                continue
            visited.add(current)
            for neighbor, weight in adj[current]:
                if neighbor not in visited:
                    new_path = path + [neighbor]
                    queue.append((neighbor, length + weight, new_path))
        return float('inf')

    # Function to find all valid paths and return the one with the minimum length
    def get_min_path(u, v):
        if u == v:
            return 0
        visited = set()
        queue = [(u, 0, [u])]
        result = None
        while queue:
            current, length, path = queue.pop(0)
            if current == v:
                result = length
                break
            if current in visited:
                continue
            visited.add(current)
            for neighbor, weight in adj[current]:
                if neighbor not in visited:
                    new_path = path + [neighbor]
                    queue.append((neighbor, length + weight, new_path))
        return result

    # Find the minimum path length from u to v
    def min_path_len(u, v):
        visited = set()
        queue = [(u, 0, [u])]
        result = float('inf')
        while queue:
            current, length, path = queue.pop(0)
            if current == v:
                result = length
                break
            if current in visited:
                continue
            visited.add(current)
            for neighbor, weight in adj[current]:
                if neighbor not in visited:
                    new_path = path + [neighbor]
                    queue.append((neighbor, length + weight, new_path))
        return result if result != float('inf') else -1

    # Maintain a list of valid nodes to consider
    valid_nodes = list(range(n))

    # List to store potential transient and recurrent states
    transient = []
    recurrent = []
    visited = set()
    for i in range(n):
        if i not in visited:
            stack = [i]
            component = []
            while stack:
                node = stack.pop()
                if node in visited:
                    continue
                visited.add(node)
                component.append(node)
                for neighbor, _ in adj[node]:
                    if neighbor not in visited:
                        stack.append(neighbor)
            # Check for cycles in this component
            # Method: perform a DFS and check for back edges
            is_recurrent = False
            for node in component:
                stack = [node]
                visited_in_dfs = set()
                while stack:
                    current = stack.pop()
                    if current in visited_in_dfs:
                        continue
                    visited_in_dfs.add(current)
                    for neighbor, _ in adj[current]:
                        if neighbor not in visited_in_dfs:
                            stack.append(neighbor)
                        elif neighbor == node:
                            is_recurrent = True
                            break
                    if is_recurrent:
                        break
                if is_recurrent:
                    break
            if is_recurrent:
                recurrent.extend(component)
            else:
                transient.extend(component)

    # Base case: all nodes are transient
    if not recurrent:
        return -1

    # Remove recurrent nodes from valid nodes as they can only exit in the transient region
    valid_nodes = [i for i in valid_nodes if i not in recurrent]

    # Build the transient part of the graph
    adj_transient = [[] for _ in range(n)]
    for u, v, w in edges:
        if u not in recurrent and v not in recurrent:
            adj_transient[u].append((v, w))

    # Function to check if all nodes in the path are valid
    def is_valid(u, v, path):
        for i in range(len(path) - 1):
            if path[i] not in valid_nodes or path[i+1] not in valid_nodes:
                return False
        return True

    # Function to compute the minimum path length from u to v
    def min_path(u, v):
        if u == v:
            return 0
        visited = set()
        queue = [(u, 0, [u])]
        result = float('inf')
        while queue:
            current, length, path = queue.pop(0)
            if current == v:
                result = length
                break
            if current in visited:
                continue
            visited.add(current)
            for neighbor, weight in adj_transient[current]:
                if neighbor not in visited:
                    new_path = path + [neighbor]
                    queue.append((neighbor, length + weight, new_path))
        return result if result != float('inf') else -1

    # Find the minimum path length from all valid transient nodes to v
    min_length = float('inf')
    for i in valid_nodes:
        length = min_path(i, valid_nodes[-1])
        if length != -1:
            min_length = min(min_length, length)

    return min_length if min_length != float('inf') else -1

