def find_min_value(lst):
    # Bubble Sort to find the minimum value
    n = len(lst)
    for i in range(n):
        for j in range(0, n - i - 1):
            if lst[j] > lst[j + 1]:
                lst[j], lst[j + 1] = lst[j + 1], lst[j]
    return lst[0] if n > 0 else None

